-- ---------- hand-written invariants (not expressible in Prisma) ----------

-- Exactly one actor reference per project-role row (user XOR group).
ALTER TABLE "ProjectRoleActor"
  ADD CONSTRAINT "projectroleactor_one_ref"
  CHECK (num_nonnulls("userId", "groupId") = 1);

-- No self-links.
ALTER TABLE "IssueLink"
  ADD CONSTRAINT "issuelink_no_self_link"
  CHECK ("outwardId" <> "inwardId");

-- fixVersions | affectsVersions only.
ALTER TABLE "IssueVersion"
  ADD CONSTRAINT "issueversion_kind_check"
  CHECK ("kind" IN ('fix', 'affects'));

-- At most one default board per project.
CREATE UNIQUE INDEX "board_one_default_per_project"
  ON "Board"("projectId") WHERE "isDefault";

-- At most one initial status per workflow.
CREATE UNIQUE INDEX "workflowstatus_one_initial"
  ON "WorkflowStatus"("workflowId") WHERE "isInitial";

-- At most one default level per security scheme.
CREATE UNIQUE INDEX "securitylevel_one_default"
  ON "SecurityLevel"("schemeId") WHERE "isDefault";

-- At most one default notification scheme instance-wide.
CREATE UNIQUE INDEX "notificationscheme_one_default"
  ON "NotificationScheme"("isDefault") WHERE "isDefault";
